 p=NaturalCradleGraspPlan(REQUEST);review=validate_review(p,PROOF);tests=json.loads((O/'software_admission_result.json').read_bytes());cam=json.loads((O/'camera_probe/result.json').read_bytes());assert tests['status']=='passed' and tests['tests_run']==25 and not tests['failures'] and not tests['errors'] and tests['controller_hashes']==hashes();assert cam['status']=='plain_camera_only_checked' and cam['motor_port_constructions']==0 and not cam['yellow_overlay_used'] and cam['camera_recording']['status']=='complete'
